23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
28	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
29	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
30	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
33	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
34	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
35	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
36	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
37	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
38	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
40	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
45	     * (e.g. for owners created before the flag existed) to {@code false} so the response
46	     * always carries an explicit boolean.
47	     */
48	    default Boolean formatPossibleDuplicate(Owner owner) {
49	        if (owner == null) {
50	            return null;
51	        }
52	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
53	    }
54	
55	    /**
56	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
57	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
58	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
59	     * birth date or its registration date is absent, since the band cannot be derived without both
60	     * dates.
61	     */
62	    default String formatAgeBand(Owner owner) {
63	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
64	            return null;
65	        }
66	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
67	        if (age < 18) {
68	            return "MINOR";
69	        }
70	        if (age < 65) {
71	            return "ADULT";
72	        }
73	        return "SENIOR";
74	    }
75	
76	    /**
77	     * Derive an owner's preferred contact channel from its stored contact details:
78	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
79	     */
80	    default String formatContactPreference(Owner owner) {
81	        if (owner == null) {
82	            return null;
83	        }
84	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
85	        return hasEmail ? "EMAIL" : "PHONE";
86	    }
87	
88	    /**
89	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
90	     * (e.g. for owners created before the flag existed) to {@code false} so the response
91	     * always carries an explicit boolean.
92	     */
93	    default Boolean formatBulkSignupWarning(Owner owner) {
94	        if (owner == null) {
95	            return null;
96	        }
97	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
98	    }
99	
100	    /**
101	     * Derive an owner's locality from its region-and-hash identity: the {@code <REGION>} segment
102	     * of the {@code customerCode} (the part before the first hyphen), which is the region code
103	     * derived from the owner's postcode. For an owner that has not yet been assigned a customer
104	     * code, the region is derived directly from the postcode (see {@link Regions#forPostcode}),
105	     * yielding the same value the code would carry. Returns {@code null} only when the owner
106	     * itself is {@code null}.
107	     */
108	    default String formatLocality(Owner owner) {
109	        if (owner == null) {
110	            return null;
111	        }
112	        String code = owner.getCustomerCode();
113	        if (code != null) {
114	            int hyphen = code.indexOf('-');
115	            return hyphen >= 0 ? code.substring(0, hyphen) : code;
116	        }
117	        return Regions.forPostcode(owner.getPostcode());
118	    }
119	
120	    /**
121	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
122	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
123	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
124	     * is {@code null} or its region is not in the table.
125	     */
126	    default String formatTimezone(Owner owner) {
127	        if (owner == null) {
128	            return null;
129	        }
130	        return Regions.timezoneForRegion(formatLocality(owner));
131	    }
132	
133	    /**
134	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
135	     * email address is present; {@code 1} when the owner has no namesakes (its
136	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
137	     * owner plus its pets); and {@code 3} when the owner's tenure (days elapsed since its
138	     * {@code registrationDate}) exceeds {@code 365}. A null or absent namesake count is treated as
139	     * not being zero, so it contributes nothing.
140	     */
141	    default Integer formatMembershipPoints(Owner owner) {
142	        if (owner == null) {
143	            return null;
144	        }
145	        int points = 0;
146	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
147	        if (hasEmail) {
148	            points += 2;
149	        }
150	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
151	        if (uniqueName) {
152	            points += 1;
153	        }
154	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
155	        if (householdSize >= 3) {
156	            points += 2;
157	        }
158	        LocalDate registrationDate = owner.getRegistrationDate();
159	        if (registrationDate != null && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
160	            points += 3;
161	        }
162	        return points;
163	    }
164	
165	    /**
166	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
167	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
168	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
169	     * and {@code 4} for {@code 6} or more.
170	     */
171	    default Integer formatMembershipLevel(Owner owner) {
172	        if (owner == null) {
173	            return null;
174	        }
175	        int points = formatMembershipPoints(owner);
176	        if (points <= 1) {
177	            return 1;
178	        }
179	        if (points <= 3) {
180	            return 2;
181	        }
182	        if (points <= 5) {
183	            return 3;
184	        }
185	        return 4;
186	    }
187	
188	    /**
189	     * Compute an owner's check digit: a single Luhn check digit (0-9) over the digits
190	     * contained in the owner's {@code customerCode}. Non-digit characters (the region segment
191	     * and any hex letters of the hash) are ignored. Returns {@code null} when the owner or its
192	     * customer code is absent, since the digit cannot be derived without the code.
193	     */
194	    default Integer formatCheckDigit(Owner owner) {
195	        if (owner == null || owner.getCustomerCode() == null) {
196	            return null;
197	        }
198	        String code = owner.getCustomerCode();
199	        int sum = 0;
200	        boolean dbl = true;
201	        for (int i = code.length() - 1; i >= 0; i--) {
202	            char c = code.charAt(i);
203	            if (c < '0' || c > '9') {
204	                continue;
205	            }
206	            int d = c - '0';
207	            if (dbl) {
208	                d *= 2;
209	                if (d > 9) {
210	                    d -= 9;
211	                }
212	            }
213	            sum += d;
214	            dbl = !dbl;
215	        }
216	        return (10 - (sum % 10)) % 10;
217	    }
218	
219	    /**
220	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
221	     * is the last two digits of the registration date year (e.g. {@code "NSW-3F5A9C2E-M26"}).
222	     * Returns {@code null} when either the customer code or registration date is absent, since
223	     * the number cannot be derived without both.
224	     */
225	    default String formatMembershipNumber(Owner owner) {
226	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
227	            return null;
228	        }
229	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
230	    }
231	
232	    /**
233	     * Format an owner's stored E.164 telephone for humans as the country code, a space, then the
234	     * national digits grouped in threes, e.g. {@code "+61412345678"} becomes
235	     * {@code "+61 412 345 678"} (see {@link E164Telephone#toDisplay}). The raw {@code telephone}
236	     * is left in E.164 form. Returns {@code null} when the owner or its telephone is absent.
237	     */
238	    default String formatTelephoneDisplay(Owner owner) {
239	        if (owner == null) {
240	            return null;
241	        }
242	        return E164Telephone.toDisplay(owner.getTelephone());
243	    }
244	
245	    /**
246	     * Compose an owner's salutation as its {@code title} followed by a single space and the
247	     * last name (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the
248	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
249	     */
250	    default String formatSalutation(Owner owner) {
251	        if (owner == null) {
252	            return null;
253	        }
254	        String title = owner.getTitle();
255	        if (title == null || title.trim().isEmpty()) {
256	            return owner.getLastName();
257	        }
258	        return title + " " + owner.getLastName();
259	    }
260	
261	    /**
262	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
263	     */
264	    default String formatDisplayName(Owner owner) {
265	        if (owner == null) {
266	            return null;
267	        }
268	        return owner.getLastName() + ", " + owner.getFirstName();
269	    }
270	
271	    /**
272	     * Format an owner's initials as the upper-cased first letters of the first and last
273	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
274	     */
275	    default String formatInitials(Owner owner) {
276	        if (owner == null) {
277	            return null;
278	        }
279	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
280	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
281	    }
282	
283	    Owner toOwner(OwnerDto ownerDto);
284	
285	    @Mapping(target = "id", ignore = true)
286	    @Mapping(target = "pets", ignore = true)
287	    @Mapping(target = "namesakeCount", ignore = true)
288	    @Mapping(target = "bulkSignupWarning", ignore = true)
289	    @Mapping(target = "possibleDuplicate", ignore = true)
290	    @Mapping(target = "possibleDuplicateOf", ignore = true)
291	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
292	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
293	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
294	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
295	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
296	    Owner toOwner(OwnerFieldsDto ownerDto);
297	
298	    /**
299	     * Normalize a postal address for storage into its canonical form (see
300	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
301	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
302	     * automatic method selection, so it only runs where a mapping explicitly references it via
303	     * {@code qualifiedByName}.
304	     */
305	    @Named("normalizeAddress")
306	    default String normalizeAddress(String address) {
307	        return AddressNormalizer.normalize(address);
308	    }
309	
310	    /**
311	     * Compose the single stored/returned {@code address} from whichever address fields the request
312	     * supplies, preferring the structured form. When a non-blank {@code addressLine1} is present the
313	     * composed value is the normalized {@code addressLine1} (see {@link AddressNormalizer}), with a
314	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
315	     * present; otherwise it falls back to the normalized flat {@code address}. This keeps everything
316	     * that reads the stored address consistent regardless of which form the caller used.
317	     */
318	    default String composeAddress(OwnerFieldsDto ownerDto) {
319	        if (ownerDto == null) {
320	            return null;
321	        }
322	        String line1 = ownerDto.getAddressLine1();
323	        if (line1 != null && !line1.trim().isEmpty()) {
324	            String composed = AddressNormalizer.normalize(line1);
325	            String line2 = ownerDto.getAddressLine2();
326	            if (line2 != null && !line2.trim().isEmpty()) {
327	                composed = composed + " " + AddressNormalizer.normalize(line2);
328	            }
329	            return composed;
330	        }
331	        return AddressNormalizer.normalize(ownerDto.getAddress());
332	    }
333	
334	    /**
335	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
336	     * The requirement that a valid E.164 number can be formed is enforced separately by
337	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
338	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
339	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
340	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
341	     */
342	    @Named("normalizeTelephone")
343	    default String normalizeTelephone(String telephone) {
344	        return E164Telephone.normalize(telephone);
345	    }
346	
347	    /**
348	     * Normalize an email address for storage by lower-casing it, so it is persisted and
349	     * returned in a canonical form regardless of the casing supplied by the caller.
350	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
351	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
352	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
353	     */
354	    @Named("normalizeEmail")
355	    default String normalizeEmail(String email) {
356	        return email == null ? null : email.toLowerCase();
357	    }
358	
359	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
360	
361	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
362	
363	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
364	        OwnerPageDto ownerPageDto = new OwnerPageDto();
365	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
366	        ownerPageDto.setPage(ownerPage.getNumber());
367	        ownerPageDto.setSize(ownerPage.getSize());
